const HOME_TOKEN_ART = {"WIF":"data:image/png;base64,","HYPE":"data:image/png;base64,","JUP":"data:image/png;base64,","BONK":"data:image/png;base64,","PENGU":"data:image/png;base64,","BTC":"data:image/svg+xml;base64,","ETH":"data:image/svg+xml;base64,","USDC":"data:image/svg+xml;base64,"};
function Logo({ id, size = M.logo }) {
  if (id === "SOL") return <LocalLogo id={id} size={size} />;
  if (HOME_TOKEN_ART[id]) return (
    <img src={HOME_TOKEN_ART[id]} alt="" width={size} height={size}
      className="shrink-0" decoding="sync"
      style={{ width: size, height: size, borderRadius: "50%", objectFit: "cover", display: "block" }} />
  );
  return <NetworkLogo id={id} size={size} />;
}

function NetworkLogo({ id, size = M.logo }) {
  const urls = WEB[id];
  const [step, setStep] = useState(0);
  const [ready, setReady] = useState(false);
  useEffect(() => { setStep(0); setReady(false); }, [id]);
  if (!urls || step >= urls.length) return <LocalLogo id={id} size={size} />;
  const tile = !!WHITE_TILE[id];
  // ask CoinGecko for the large asset rather than the thumbnail
  const url = String(urls[step]).replace(/\/(thumb|small)\//, "/large/");
  return (
    <div className="relative flex shrink-0 items-center justify-center overflow-hidden"
      style={{ width: size, height: size, borderRadius: "50%", background: tile ? "#FFFFFF" : P.card2 }}>
      <img src={url} alt="" decoding="sync" fetchpriority="high" referrerPolicy="no-referrer"
        onError={() => { forgetLogo(id, url); setStep((n) => n + 1); }}
        onLoad={() => setReady(true)}
        style={{
          width: tile ? size * 0.74 : size,
          height: tile ? size * 0.74 : size,
          objectFit: tile ? "contain" : "cover",
          borderRadius: tile ? 0 : "50%",
          display: "block",
          imageRendering: "auto",
        }} />
    </div>
  );
}

