/* ============ helpers ============ */
const money = (n, d) => "$" + n.toLocaleString("en-US", { minimumFractionDigits: d === undefined ? 2 : d, maximumFractionDigits: d === undefined ? 2 : d });
const compact = (n) => {
  const a = Math.abs(n);
  if (a >= 1e9) return (n / 1e9).toFixed(2) + "B";
  if (a >= 1e6) return (n / 1e6).toFixed(2) + "M";
  if (a >= 1e3) return (n / 1e3).toFixed(2) + "K";
  return n.toLocaleString("en-US", { maximumFractionDigits: 2 });
};
const pctStr = (n) => (n >= 0 ? "+" : "") + n.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + "%";
const sh = (n) => n.toLocaleString("en-US", { maximumFractionDigits: n < 10 ? 4 : 2 });
const SUBS = "\u2080\u2081\u2082\u2083\u2084\u2085\u2086\u2087\u2088\u2089";
// $0.0₅1234 — how every DEX renders long-tail prices
function subPrice(n) {
  if (!n || n <= 0) return "$0";
  if (n >= 1) return "$" + n.toLocaleString("en-US", { maximumFractionDigits: 2 });
  if (n >= 0.001) return "$" + n.toFixed(5).replace(/0+$/, "");
  const e = Math.floor(Math.log10(n));
  const zeros = -e - 1;
  const digits = Math.round(n * Math.pow(10, e < 0 ? -e + 3 : 4)).toString().slice(0, 4);
  return "$0." + (zeros > 1 ? "0" + String(zeros).split("").map((d) => SUBS[+d]).join("") : "0".repeat(zeros)) + digits;
}

function chime() {
  try {
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    const ac = new Ctx();
    const o = ac.createOscillator(), g = ac.createGain();
    o.connect(g); g.connect(ac.destination);
    o.type = "sine";
    o.frequency.setValueAtTime(880, ac.currentTime);
    o.frequency.setValueAtTime(1320, ac.currentTime + 0.09);
    g.gain.setValueAtTime(0.0001, ac.currentTime);
    g.gain.exponentialRampToValueAtTime(0.25, ac.currentTime + 0.02);
    g.gain.exponentialRampToValueAtTime(0.0001, ac.currentTime + 0.42);
    o.start(); o.stop(ac.currentTime + 0.45);
    setTimeout(() => { try { ac.close(); } catch (e) {} }, 700);
  } catch (e) {}
}

const NATIVE = () => (typeof window !== "undefined" && window.__NATIVE__ &&
  window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.native) || null;
const native = (action, extra) => {
  const n = NATIVE();
  if (!n) return false;
  try { n.postMessage({ action, ...(extra || {}) }); return true; } catch (e) { return false; }
};

const haptic = (kind) => {
  if (native("haptic", { style: kind || "light" })) return;
  try {
    const H = window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.Haptics;
    if (H) { kind === "heavy" ? H.impact({ style: "HEAVY" }) : kind === "light" ? H.impact({ style: "LIGHT" }) : H.impact({ style: "MEDIUM" }); return; }
    if (navigator.vibrate) navigator.vibrate(kind === "heavy" ? 24 : kind === "light" ? 8 : 14);
  } catch (e) {}
};

