function series(seed, up, len = 44) {
  let s = 0;
  for (let i = 0; i < seed.length; i++) s = (s * 31 + seed.charCodeAt(i)) % 9973;
  const rnd = () => ((s = (s * 1103515245 + 12345) % 2147483648) / 2147483648);
  let v = 100;
  return Array.from({ length: len }, (_, i) => { v += (rnd() - 0.46) * 3.4 + (up ? 0.3 : -0.28) * (i / len) * 3; return v; });
}
function Line({ data, up, h = 140 }) {
  const w = 340;
  const min = Math.min(...data), max = Math.max(...data), span = max - min || 1;
  const pts = data.map((v, i) => [(i / (data.length - 1)) * w, h - ((v - min) / span) * (h - 16) - 8]);
  const col = up ? P.up : P.down;
  return (
    <svg viewBox={"0 0 " + w + " " + h} className="w-full" style={{ height: h, color: col }} preserveAspectRatio="none">
      <polyline points={pts.map((p) => p.join(",")).join(" ")} fill="none" stroke="currentColor" strokeWidth="3" strokeLinejoin="round" strokeLinecap="round" />
      <circle cx={pts[pts.length - 1][0]} cy={pts[pts.length - 1][1]} r="5" fill="currentColor" />
    </svg>
  );
}
function MiniLine({ data, up, w = 74, h = 30 }) {
  const min = Math.min(...data), max = Math.max(...data), span = max - min || 1;
  return <svg width={w} height={h} style={{ color: up ? P.up : P.down }}><polyline points={data.map((v, i) => (i / (data.length - 1)) * w + "," + (h - ((v - min) / span) * (h - 4) - 2)).join(" ")} fill="none" stroke="currentColor" strokeWidth="2" strokeLinejoin="round" /></svg>;
}
function Rank({ n }) {
  const col = n === 1 ? "#F2C94C" : n === 2 ? "#C6CBD1" : "#E8663A";
  return <div className="absolute flex items-center justify-center rounded-full" style={{ width: 19, height: 19, right: -2, bottom: -2, background: col, color: "#0B0B0D", fontSize: 10, fontWeight: 800, boxShadow: "0 0 0 2px " + P.bg }}>{n}</div>;
}

