function Frost({ dir = "top", offset = 0 }) {
  const top = dir === "top";
  // progressive blur: strongest at the edge, tapering to nothing so it blends into the content
  const layers = [
    { blur: 3, stop: 100 },
    { blur: 7, stop: 74 },
    { blur: 12, stop: 46 },
  ];
  const mask = (stop) =>
    top
      ? "linear-gradient(to bottom, #000 0%, #000 " + stop * 0.55 + "%, transparent " + stop + "%)"
      : "linear-gradient(to top, #000 0%, #000 " + stop * 0.55 + "%, transparent " + stop + "%)";
  const tint = top
    ? "linear-gradient(to bottom, rgba(0,0,0,0.32) 55%, rgba(0,0,0,0.14) 82%, rgba(0,0,0,0))"
    : "linear-gradient(to top, rgba(0,0,0,0.26) 55%, rgba(0,0,0,0.10) 84%, rgba(0,0,0,0))";
  const base = {
    position: "absolute", left: 0, right: 0, zIndex: 0,
    top: top ? 0 : offset, bottom: top ? -6 : 0,
    pointerEvents: "none",
  };
  return (
    <div aria-hidden="true" style={{ ...base }}>
      {layers.map((l) => (
        <div key={l.blur} style={{
          position: "absolute", inset: 0,
          backdropFilter: "blur(" + l.blur + "px) saturate(150%)",
          WebkitBackdropFilter: "blur(" + l.blur + "px) saturate(150%)",
          maskImage: mask(l.stop), WebkitMaskImage: mask(l.stop),
        }} />
      ))}
      <div style={{ position: "absolute", inset: 0, background: tint }} />
    </div>
  );
}

