function candles(seed, n, base) {
  let s = 0;
  for (let i = 0; i < seed.length; i++) s = (s * 31 + seed.charCodeAt(i)) % 9973;
  const rnd = () => ((s = (s * 1103515245 + 12345) % 2147483648) / 2147483648);
  const out = [];
  let px = base * (0.97 + rnd() * 0.02);
  for (let i = 0; i < n; i++) {
    const drift = (rnd() - 0.5) * base * 0.006;
    const o = px;
    const c = Math.max(base * 0.5, o + drift);
    const h = Math.max(o, c) + rnd() * base * 0.003;
    const l = Math.min(o, c) - rnd() * base * 0.003;
    out.push({ o, h, l, c });
    px = c;
  }
  // pin the final candle to the live price
  const last = out[out.length - 1];
  last.c = base;
  last.h = Math.max(last.h, base);
  last.l = Math.min(last.l, base);
  return out;
}

function LineChart({ data, onScrub, scrub, range }) {
  scrub = scrub == null ? null : Math.min(scrub, data.length - 1);
  const W = 393, H = 250;
  const closes = data.map((d) => d.c);
  const hi = Math.max(...closes), lo = Math.min(...closes);
  const span = hi - lo || 1;
  const x = (i) => (i / (data.length - 1)) * W;
  const y = (v) => H - ((v - lo) / span) * (H - 40) - 20;
  const up = closes[closes.length - 1] >= closes[0];
  const col = up ? P.up : P.down;

  const segment = (from, to) => {
    let path = "M" + x(from).toFixed(1) + " " + y(closes[from]).toFixed(1);
    for (let i = from + 1; i <= to; i++) path += " L" + x(i).toFixed(1) + " " + y(closes[i]).toFixed(1);
    return path;
  };
  const selected = scrub == null ? closes.length - 1 : scrub;
  const ex = x(closes.length - 1), ey = y(closes[closes.length - 1]);

  const pick = (e) => {
    if (!onScrub) return;
    const r = e.currentTarget.getBoundingClientRect();
    const cx = ("touches" in e ? e.touches[0].clientX : e.clientX) - r.left;
    onScrub(Math.max(0, Math.min(data.length - 1, Math.round((cx / r.width) * (data.length - 1)))));
  };

  return (
    <svg viewBox={"0 0 " + W + " " + H} width="100%" style={{ height: H, touchAction: "none", display: "block", color: col }}
      onPointerDown={e => { e.stopPropagation(); e.currentTarget.setPointerCapture(e.pointerId); pick(e); }} onPointerMove={(e) => { e.stopPropagation(); if (e.buttons || e.currentTarget.hasPointerCapture(e.pointerId)) pick(e); }}
      onPointerUp={e => { e.stopPropagation(); if (e.currentTarget.hasPointerCapture(e.pointerId)) e.currentTarget.releasePointerCapture(e.pointerId); onScrub && onScrub(null); }} onPointerCancel={() => onScrub && onScrub(null)}>
      <line x1="0" x2={W} y1={y(closes[0])} y2={y(closes[0])} stroke="#424246" strokeWidth="0.8" strokeDasharray="2.5 3" />
      {scrub != null && scrub < closes.length - 1 && <path d={segment(scrub, closes.length - 1)} fill="none" stroke="#222225" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" />}
      <path d={segment(0, selected)} fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" />
      {scrub == null && <><circle cx={ex} cy={ey} r="11" fill="currentColor" opacity="0.22" /><circle cx={ex} cy={ey} r="4.5" fill="currentColor" /></>}
      {scrub != null && (
        <g>
          <line x1={x(scrub)} x2={x(scrub)} y1="18" y2={H} stroke="#77777B" strokeWidth="1" />
          <text x={Math.max(34, Math.min(W - 34, x(scrub)))} y="15" textAnchor="middle" fill="#EEEEF0" fontSize="10" fontWeight="600">{chartTime(data[scrub].t, range)}</text>
          <circle cx={x(scrub)} cy={y(closes[scrub])} r="5" fill="currentColor" />
        </g>
      )}
    </svg>
  );
}

function Candles({ data, onScrub, scrub }) {
  scrub = scrub == null ? null : Math.min(scrub, data.length - 1);
  const W = 393, H = 250, plotW = 340;
  const hi = Math.max(...data.map((d) => d.h)), lo = Math.min(...data.map((d) => d.l));
  const span = hi - lo || 1;
  const y = (v) => H - ((v - lo) / span) * (H - 20) - 10;
  const cw = plotW / data.length;
  const last = data[data.length - 1];

  const pick = (e) => {
    if (!onScrub) return;
    const r = e.currentTarget.getBoundingClientRect();
    const x = ("touches" in e ? e.touches[0].clientX : e.clientX) - r.left;
    const i = Math.max(0, Math.min(data.length - 1, Math.floor((x / r.width) * (W / plotW) * data.length)));
    onScrub(i);
  };

  return (
    <svg viewBox={"0 0 " + W + " " + H} width="100%" style={{ height: H, touchAction: "none", display: "block" }}
      onPointerDown={e => { e.stopPropagation(); e.currentTarget.setPointerCapture(e.pointerId); pick(e); }} onPointerMove={(e) => { e.stopPropagation(); if (e.buttons || e.currentTarget.hasPointerCapture(e.pointerId)) pick(e); }}
      onPointerUp={e => { e.stopPropagation(); if (e.currentTarget.hasPointerCapture(e.pointerId)) e.currentTarget.releasePointerCapture(e.pointerId); onScrub && onScrub(null); }} onPointerCancel={() => onScrub && onScrub(null)}>
      {[0.2, 0.5, 0.8].map((f) => <g key={f}><line x1="0" x2={plotW} y1={H * f} y2={H * f} stroke="#1D1D20" strokeWidth="0.8" /><text x={plotW + 5} y={H * f + 3} fill="#A8A8AE" fontSize="9">{(hi - f * span).toFixed(1)}</text></g>)}
      {[0.2, 0.5, 0.8].map((f) => <line key={"v" + f} x1={plotW * f} x2={plotW * f} y1="0" y2={H} stroke="#18181B" strokeWidth="0.8" />)}
      {data.map((d, i) => {
        const up = d.c >= d.o, col = up ? P.up : P.down;
        const cx = i * cw + cw / 2;
        return (
          <g key={i} style={{ color: col }}>
            <line x1={cx} x2={cx} y1={y(d.h)} y2={y(d.l)} stroke="currentColor" strokeWidth="1.1" />
            <rect x={cx - cw * 0.32} y={Math.min(y(d.o), y(d.c))} width={cw * 0.64}
              height={Math.max(1.2, Math.abs(y(d.o) - y(d.c)))} fill="currentColor" rx="0.6" />
          </g>
        );
      })}
      <line x1="0" x2={plotW} y1={y(last.c)} y2={y(last.c)} stroke="#77777C" strokeWidth="1" strokeDasharray="3 4" />
      <rect x={plotW} y={y(last.c) - 9} width={W - plotW} height="18" rx="9" fill="#343438" />
      <text x={plotW + 5} y={y(last.c) + 3} fill="#FFFFFF" fontSize="9" fontWeight="700">{last.c.toFixed(1)}</text>
      {scrub != null && (
        <g>
          <line x1={scrub * cw + cw / 2} x2={scrub * cw + cw / 2} y1="0" y2={H} stroke="#8E8E93" strokeWidth="1" />
          <circle cx={scrub * cw + cw / 2} cy={y(data[scrub].c)} r="3.5" fill="#fff" />
        </g>
      )}
    </svg>
  );
}

