function DragSheet({ onClose, children, style, full }) {
  const [dy, setDy] = useState(0);
  const startRef = React.useRef(null);
  const down = (e) => { startRef.current = e.clientY; };
  const move = (e) => {
    if (startRef.current == null) return;
    const d = e.clientY - startRef.current;
    if (d > 0) setDy(d);
  };
  const up = () => {
    if (startRef.current == null) return;
    if (dy > 110) { startRef.current = null; setDy(0); onClose(); return; }
    startRef.current = null; setDy(0);
  };
  return (
    <div
      className="anim-sheet w-full"
      style={{ ...style, transform: dy ? "translateY(" + dy + "px)" : undefined, transition: startRef.current == null ? "transform 240ms cubic-bezier(.22,.9,.28,1)" : "none" }}
      onPointerDown={down} onPointerMove={move} onPointerUp={up} onPointerCancel={up}
    >
      <div className="mx-auto mb-3 h-1.5 w-10 shrink-0 rounded-full" style={{ background: "#3A3A3E", marginTop: full ? 6 : 0 }} />
      {children}
    </div>
  );
}

function AmountScreen({ title, subtitle, right, onClose, chips, amount, sub, methodLabel, onMethod, presets, onKey, cta, ctaOn, onCta, prefix = "$", videoStyle = false }) {
  const [dy, setDy] = React.useState(0);
  const [closing, setClosing] = React.useState(false);
  const exitTimer = React.useRef(null);
  React.useEffect(() => () => clearTimeout(exitTimer.current), []);
  const dismiss = () => { if (closing) return; setClosing(true); exitTimer.current = setTimeout(onClose, matchMedia("(prefers-reduced-motion: reduce)").matches ? 0 : 220); };
  const start = React.useRef(null);
  const grab = {
    onPointerDown: (e) => { start.current = e.clientY; },
    onPointerMove: (e) => { if (start.current != null) { const d = e.clientY - start.current; setDy(d > 0 ? d : 0); } },
    onPointerUp: () => { if (start.current == null) return; start.current = null; if (dy > 90) dismiss(); setDy(0); },
    onPointerCancel: () => { start.current = null; setDy(0); },
  };
  const hasAmount = Number(String(amount).replace(/,/g, "")) > 0;
  const amountSize = Math.min(96, Math.max(48, 350 / ((String(amount || "0").length + prefix.length) * 0.62)));
  const actionButton = <div style={{ paddingLeft: videoStyle ? 24 : 24, paddingRight: 24, paddingBottom: videoStyle ? 12 : "calc(14px + env(safe-area-inset-bottom))", paddingTop: 6 }}>
    <button onClick={onCta} disabled={!ctaOn} className="w-full rounded-full active:opacity-80"
      style={{ background: ctaOn ? P.purple : P.card, color: ctaOn ? "#0B0B0D" : P.dim, height: 54, fontSize: 18, fontWeight: 700 }}>{cta}</button>
  </div>;
  return (
    <div className={"anim-sheet fixed inset-0 z-[86] flex flex-col" + (closing ? " ph-exiting" : "")}
      style={{ background: P.bg,
        transform: dy ? "translateY(" + dy + "px)" : undefined,
        transition: start.current == null ? "transform 260ms cubic-bezier(.32,.72,0,1)" : "none" }}>
      <div className="mx-auto flex h-full min-h-0 w-full flex-col overflow-hidden" style={{ maxWidth: M.screen, paddingTop: videoStyle ? "calc(15px + env(safe-area-inset-top))" : "calc(6px + env(safe-area-inset-top))" }}>
        {!videoStyle && <div {...grab} className="flex w-full shrink-0 items-center justify-center" style={{ height: 34, touchAction: "none" }}>
          <div className="h-1.5 w-10 rounded-full" style={{ background: "#3A3A3E" }} />
        </div>}
        <div className="flex shrink-0 items-center gap-3.5" style={{ paddingLeft: M.pad, paddingRight: M.pad, paddingBottom: 8 }}>
          <button onClick={dismiss} className="flex items-center justify-center rounded-full active:opacity-60"
            style={{ width: 40, height: 40, background: P.pill }}>{I.x(20, "#FFFFFF")}</button>
          <div className="min-w-0 flex-1"><div style={{ fontSize: videoStyle ? 18 : 22, fontWeight: 700, letterSpacing: "-0.02em" }}>{title}</div>{subtitle && <div style={{ color: P.dim, fontSize: 16 }}>{subtitle}</div>}</div>
          {right}
        </div>

        {chips}

        <div className="flex min-h-0 flex-1 flex-col justify-center overflow-hidden" style={{ paddingLeft: 29, paddingRight: 20 }}>
          <div className="w-full truncate" style={{
            fontSize: videoStyle ? amountSize : "clamp(3rem, 26vw, 6.5rem)", fontWeight: videoStyle ? 400 : 700, letterSpacing: videoStyle ? "-0.04em" : "-0.045em", lineHeight: 1,
            color: amount && amount !== "0" ? P.text : "#A8A8AD", fontVariantNumeric: "tabular-nums" }}>
            {prefix}{amount || "0"}
          </div>
          {sub && <div className="mt-2.5" style={{ color: "#A8A8AD", fontSize: 17 }}>{sub}</div>}
        </div>

        {methodLabel && (
          <button onClick={onMethod} className="flex w-full items-center justify-between active:opacity-60"
            style={{ paddingLeft: 24, paddingRight: 24, paddingBottom: 18 }}>
            <span className="truncate" style={{ fontSize: videoStyle ? 16 : 20, fontWeight: videoStyle ? 500 : 800 }}>{methodLabel}</span>
            {!videoStyle && I.caret(20, "#FFFFFF")}
          </button>
        )}

        {presets && (!videoStyle || !hasAmount) && (
          <div className="flex justify-between" style={{ paddingLeft: 24, paddingRight: 24 }}>
            {presets.map((q) => (
              <button key={q[0]} onClick={q[1]} className="rounded-full active:opacity-60"
                style={{ background: P.card, width: "31.5%", height: 48, fontSize: videoStyle ? 16 : 20, fontWeight: videoStyle ? 500 : 700 }}>{q[0]}</button>
            ))}
          </div>
        )}
        {videoStyle && hasAmount && actionButton}

        <div className="shrink-0 grid grid-cols-3" style={{ paddingLeft: 24, paddingRight: 24, paddingTop: 10 }}>
          {["1","2","3","4","5","6","7","8","9",".","0","⌫"].map((k) => (
            <button key={k} onClick={() => onKey(k)} className="flex items-center justify-center active:opacity-40"
              style={{ height: videoStyle ? 64 : 58, fontSize: videoStyle ? 26 : 24, fontWeight: 400 }}>
              {k === "⌫" ? I.back(24, "#FFFFFF") : k}
            </button>
          ))}
        </div>

        {!videoStyle && actionButton}
        {videoStyle && <div style={{ height: "calc(12px + env(safe-area-inset-bottom))", flexShrink: 0 }} />}
      </div>
    </div>
  );
}

