                      const has = alerts.some((a) => a.sym === sym);
                      if (has) { setAlerts((as) => as.filter((a) => a.sym !== sym)); flash("Alert removed"); }
                      else { setAlerts((as) => [...as, { sym, target: px2 * 1.05, dir: "above" }]); flash("Alert set at " + subPrice(px2 * 1.05)); }
